function layerProgressMarkup(p){
  const complete=p.total>0&&p.completed===p.total;
  const message=complete?(p.upcomingIds.length?'Available training complete':'Training complete'):p.completed?(p.percent>=75?'Nearly there':p.percent>=50?'Halfway there':'Building momentum'):p.inProgress?"You’re underway":p.total?'Ready for your first step':p.upcomingIds.length?'Training coming soon':p.configured?'Choose your first course':'Personalise your path';
  return `<span class="layer-progress"><span class="layer-progress-count"><span><strong>${p.completed}</strong>${p.total?`<span class="layer-progress-total"> / ${p.total}</span>`:''}</span>${p.total?`<span class="layer-progress-percent">${complete?icon('check',true):''}${p.percent}%</span>`:''}</span><span class="layer-progress-label">${p.total?'training completed':'training selected'}</span><span class="layer-progress-track" aria-hidden="true"><span style="width:${p.percent}%"></span></span><span class="layer-progress-message">${message}</span><span class="layer-progress-notes">${[p.shared?`${p.shared} shared with Foundation`:'',p.upcomingIds.length?`+ ${p.upcomingIds.length} upcoming`:'',p.optionIds.length?`${p.optionIds.length}${p.total?' more':''} option${p.optionIds.length===1?'':'s'} to explore`:''].filter(Boolean).map(t=>`<span>${t}</span>`).join('')}</span></span>`;
}
function pathSummary(profile=learner.profile,interactive=true){
  const specs=selectedRoles(profile),counts=interactive?pathwayProgress(B,learner,currentLayers):null;
  const parts=[['foundation','01','Foundation','Included for everyone'],['level','02',`L${profile.level} · ${PATH_LEVELS[profile.level-1].name.split(' · ')[1]}`,'Target work level'],['specialist','03','Specialisations',specs.length?specs.map(s=>s.name).join(' · ')+(profile.pendingSpecialisms?.length?' · Previous responsibilities awaiting role confirmation':''):profile.pendingSpecialisms?.length?'Confirm roles for previous responsibilities':'Choose one or more roles'],['tool','04','Tools',profile.tools.length?profile.tools.join(' · '):'Choose one or more']];
  return `<div class="path-composition" aria-label="Your four learning layers">${parts.map(([kind,n,title,detail])=>{
    const p=counts?.[kind],complete=p?.total>0&&p.completed===p.total;
    const label=p?`${title}. ${p.completed} of ${p.total} training completed.${p.upcomingIds.length?` ${p.upcomingIds.length} upcoming.`:''}${p.optionIds.length?` ${p.optionIds.length} more options to explore.`:''} View training.`:'';
    return `<${interactive?'button type="button"':'div'} class="composition-layer ${kind}${p?' has-progress':''}${complete?' is-complete':''}" ${interactive?`data-action="layer-jump" data-kind="${kind}" aria-label="${esc(label)}"`:''}><span class="layer-number" aria-hidden="true">${complete?icon('check',true):n}</span><strong>${esc(title)}</strong><span class="composition-detail">${esc(detail)}</span>${p?layerProgressMarkup(p):''}</${interactive?'button':'div'}>`;
  }).join('')}</div>`;
}
function layerMatches(c,layer){return c&&(layer.centralIds.includes(c.id)||layer.internalIds.includes(c.id)||(layer.kind==='tool'?c.track==='tool'&&matchesTool(c,[layer.tool]):layer.requirements.some(r=>(c.scores[r.id]?.score||0)>=2)));}
function layerOfferings(layer){
  const map=courseMap(B),central=[...layer.centralIds,...layer.internalIds].map(id=>map.get(id)).filter(Boolean),available=central.filter(c=>!unavailable(c));
  // Sequence central practice from the starting point, retaining every target level.
  if(layer.kind==='level'){const start=startingPoint(learner.profile).level,assignedLevel=c=>centralStep(layer,c)??learner.profile.level,order=c=>assignedLevel(c)>=start?assignedLevel(c)-start:10+assignedLevel(c);available.sort((a,b)=>order(a)-order(b));}
  const suggested=layer.suggestions||[];
  available.sort((a,b)=>Number(layer.roleOptionIds.includes(a.id))-Number(layer.roleOptionIds.includes(b.id)));
  const choices=[...new Map([...available.map(course=>({course,suggested:false})),...suggested.map(r=>({...r,suggested:true}))].map(x=>[x.course.id,x])).values()];
  const directCount=available.filter(c=>!layer.roleOptionIds.includes(c.id)).length,roleCount=available.length-directCount;
  const shown=choices.slice(0,2),more=choices.slice(2),upcoming=central.filter(c=>unavailable(c));
  const supported=choices.length?[]:centralItems(B,learner).filter(c=>!unavailable(c)&&layerMatches(c,layer));
  return `<div class="layer-offerings">${layer.reviewStatus?`<p class="pathway-review-label">${tag(layer.reviewStatus,layer.reviewStatus==='Reviewed'?'reviewed':'amber')}</p>`:''}${layer.kind==='level'&&B.scenario.schema===3&&learner.profile.level===1?'<p class="tiny-note">Your reviewed L1 selection reuses the two courses in Foundation. Complete them once; the options below are additional suggestions.</p>':''}${layer.kind==='level'&&B.scenario.schema===3&&learner.profile.level>1&&B.scenario.components.some(c=>c.id===`l${learner.profile.level}-coached`)?`<label class="field pathway-route"><span>Learning route</span><select name="learning-route" aria-label="Learning route">${options([['standard','Standard course route'],['coached','Coached practice route']],learner.profile.learningRoute||'standard')}</select><small>The coached route uses proposed internal practice. Your existing commitments remain in My learning.</small></label>`:''}${layer.kind==='specialist'||layer.kind==='tool'?`<div class="layer-topic"><h3>${esc(layer.reused?'Shared AI-risk learning':layer.name)}</h3>${button('Search this area','layer-search',`data-layer="${esc(layer.id)}"`,'text-link')}</div>`:''}<div class="layer-sources"><span>${directCount} central recommendation${directCount===1?'':'s'}${roleCount?` · ${roleCount} central role option${roleCount===1?'':'s'}`:''}${!layer.reviewStatus&&B.scenario.status==='Draft'&&available.length?' · Draft':''}</span><span>${suggested.length} tailored option${suggested.length===1?'':'s'}</span></div>${layer.kind==='tool'?`<p class="tiny-note">${layer.uses.length?`For: ${layer.uses.map(id=>esc(TOOL_USES.find(u=>u.id===id).name)).join(' · ')}. Task fit uses catalog descriptions; it does not add assessed coverage.`:learner.profile.quickSetup?`Suggestions use your selected tool and L${learner.profile.level} level. You can refine tool tasks in My profile.`:'Choose what you do with this tool in My profile to get tailored suggestions.'} All other offerings remain searchable.</p>`:''}${!layer.groups.length&&layer.kind==='specialist'?'<p class="tiny-note">No central selection is published for this responsibility. The options below use the catalog’s recorded teaching.</p>':''}${shown.length?`<div class="course-grid">${shown.map(x=>courseCard(x.course,x.reason,x.suggested,layer)).join('')}</div>`:supported.length?`<div class="layer-empty"><strong>Supported by learning in another layer</strong>${supported.map(c=>`<p>${button(esc(c.title),'course',`data-id="${esc(c.id)}"`,'text-link')} ${statusTag(c.id)}</p>`).join('')}<small>Shared courses count once in your personal plan.</small></div>`:`<div class="layer-empty"><strong>${Object.values(learner.items).length?'Review your selected learning or explore more options':'Explore the training available for this layer'}</strong><p>No additional suitable recommendation is available right now. Search this area to review the full offering.</p>${button('Search this layer','layer-search',`data-layer="${esc(layer.id)}"`,'small')}</div>`}${more.length?`<details class="layer-more"><summary>See ${more.length} more option${more.length===1?'':'s'}</summary><div class="course-grid">${more.map(x=>courseCard(x.course,x.reason,x.suggested,layer)).join('')}</div></details>`:''}${upcoming.length?`<details class="layer-more"><summary>${upcoming.length} option${upcoming.length===1?'':'s'} coming later or awaiting review</summary><p class="tiny-note">Save these for later. They cannot be committed until available.</p>${upcoming.map(c=>`<div class="pending-row"><div><strong>${esc(c.title)}</strong><small style="display:block">${esc(c.status||c.review)}</small>${reviewTag(c.id)}</div>${button('Save','save-course',`data-id="${esc(c.id)}"`,'small')}</div>`).join('')}</details>`:''}</div>`;
}
function roleOfferings(layer){
  return `<section class="role-recommendations" aria-label="${esc(layer.name)}"><div class="role-recommendations-title"><span class="role-number">${layer.customScope?'+':layer.pending?'?':layer.roleId}</span><div><h3>${esc(layer.name)}</h3><p>${layer.customScope?esc(layer.description):layer.reused?'Shared learning reused in this role; courses and outcomes count once.':layer.pending?'Your previous learning scope is retained until you confirm the relevant roles.':`${layer.responsibilities.length} selected responsibilit${layer.responsibilities.length===1?'y':'ies'}`}</p></div></div>${layer.customScope?layerOfferings(layer):layer.reused?`${layerOfferings(layer)}<div class="reuse-links"><span>Also reuse your selected tool training:</span>${learner.profile.tools.map(tool=>button(esc(tool),'layer-search',`data-layer="${esc('tool:'+tool)}"`,'small')).join('')}<small>No additional specialist package is required for this role.</small></div>`:layer.responsibilities.map(layerOfferings).join('')}</section>`;
}
function forYouView(){
  const categories=[['foundation','01','Foundation','A shared starting point for everyone.'],['level','02',PATH_LEVELS[learner.profile.level-1].name,PATH_LEVELS[learner.profile.level-1].description+(learner.profile.level>1?' Earlier-level practice is included where needed.':'')],['specialist','03','Your specialisations','Your selected roles, with learning for each responsibility.'],['tool','04','Your tools','Build practical skills with the tools you use.']];
  const incomplete=!learner.onboarding||!learner.profile.roles.length||!learner.profile.tools.length||needsRoleReview(learner.profile);
  return `${intro('Your learning, layer by layer.','Foundation + one AI level + your specialisations + your tools.',button(`${icon('compass')} Explore training`,'nav','data-view="explore"'))}${B.scenario.publication?`<div class="notice info publication-status"><span><strong>${esc(B.scenario.name)}</strong><br>Foundation and L1: Reviewed. Other pathways: AI recommendation - to be reviewed. Proposed internal training is shown as upcoming.</span></div>`:''}<div class="main-grid"><div class="main-column"><section class="path-overview"><div class="section-head"><div><div class="eyebrow">BUILT AROUND YOU</div><h2>Four layers. One personal path.</h2></div>${button('Edit my path','nav','data-view="profile"','small')}</div>${pathSummary()}<p class="path-progress-explanation">Progress tracks available central training and courses you add. Shared learning advances each relevant layer and counts once in your plan. Completion is self-reported.</p>${startingGuidance(learner.profile)}<div class="path-overview-footer"><p>Central recommendations and tailored options sit in each layer. Adding a course makes it your choice.</p>${incomplete?button('Complete my path','onboarding','','primary small'):button('Review central recommendations','accept-path','','small')}</div></section>${incomplete?`<div class="notice info">${icon('layers')}<span>Choose your AI level, broad responsibilities, and planned tools to complete your path. Your existing learning is preserved.</span></div>`:''}${categories.map(([kind,n,title,description])=>{const layers=currentLayers.filter(l=>l.kind===kind);return `<section class="learning-layer ${kind}" id="layer-${kind}" aria-labelledby="heading-${kind}"><header class="layer-heading"><span class="layer-number">${n}</span><div><h2 id="heading-${kind}" tabindex="-1">${esc(title)}</h2><p>${esc(description)}</p></div>${kind==='foundation'?tag('Always included'):button('Edit','nav','data-view="profile"','small ghost')}</header>${layers.length?layers.map(l=>l.kind==='specialist'?roleOfferings(l):layerOfferings(l)).join(''):`<div class="layer-empty"><strong>Choose your ${kind==='tool'?'tools':'specialisations'}</strong><p>Your recommendations will appear here as soon as you select them.</p>${button('Choose now','nav','data-view="profile"','small')}</div>`}</section>`;}).join('')}<p class="tiny-note">A course may support several layers. It is counted once in your plan and total learning time. ${B.scenario.status==='Draft'?'Central recommendations are currently a draft.':''}</p></div>${sidePanel()}</div>`;
}
function exploreView(){return `${intro('Find your next useful skill.','Search the full catalog and build a path that works for you.')}<div class="main-grid"><div class="main-column"><div class="search-box">${icon('search')}<input id="course-search" type="search" aria-label="Search training" placeholder="Search a topic, tool, course, or provider…" value="${esc(ui.query)}" autocomplete="off"><span class="tag">${B.catalogue.courses.length}</span></div><div class="filter-row">${[['relevant','For my work'],['short','2 hours or less'],['myTools','My tools'],['saved','My saved & selected']].map(([key,label])=>button(label,'filter',`data-filter="${key}" aria-pressed="${!!ui.filters[key]}"`,`chip ${ui.filters[key]?'active':''}`)).join('')}${button(`${icon('filter',true)} Filters`,'filters-toggle',`aria-expanded="${ui.showFilters}"`,'chip')}${Object.keys(ui.filters).some(k=>k!=='sort'&&ui.filters[k])?button('Clear','clear-filters','','chip'):''}</div>${ui.showFilters?`<div class="filters-more"><label>Specialisation<select id="filter-specialisation" aria-label="Specialisation">${options([['','All specialisations']],ui.filters.specialisation||'')}<optgroup label="Roles">${options(LEARNING_ROLES.map(r=>[`role:${r.id}`,r.name]),ui.filters.specialisation||'')}</optgroup><optgroup label="Specific responsibilities">${options(SPECIALISMS.map(s=>[s.id,responsibilityName(s.id)]),ui.filters.specialisation||'')}</optgroup></select></label><label>Tool<select id="filter-tool" aria-label="Tool">${options([['','All tools'],...toolsList],ui.filters.tool||'')}</select></label><label>Track<select id="filter-track">${options([['','All tracks'],...TRACK_NAMES],ui.filters.track||'')}</select></label><label>Provider<select id="filter-provider">${options([['','All providers'],...[...new Set(B.catalogue.courses.map(c=>c.provider))].sort()],ui.filters.provider||'')}</select></label><label>Resource type<select id="filter-type">${options([['','All types'],...[...new Set(B.catalogue.courses.map(c=>c.type))].sort()],ui.filters.type||'')}</select></label><label class="check-line"><input id="filter-available" type="checkbox" ${ui.filters.available?'checked':''}> Hide offerings awaiting validation</label></div>`:''}${ui.filters.layer?`<div class="notice info">Layer: ${esc(flattenLayers(currentLayers).find(l=>l.id===ui.filters.layer)?.name||'Your path')}. ${button('Show all training','clear-filters','','banner-link')}</div>`:''}${ui.filters.need?`<div class="notice info">Showing teaching for ${esc(NEED_TITLES[ui.filters.need]||ui.filters.need)}. ${button('Show all needs','clear-need','','banner-link')}</div>`:''}<div id="explore-results">${exploreResults()}</div></div>${sidePanel()}</div>`;}
function exploreResults(){const result=searchCourses(B,learner,ui.query,ui.filters),size=12,pages=Math.max(1,Math.ceil(result.length/size));ui.page=Math.min(ui.page,pages-1);return `<div class="results-head"><span><strong>${result.length}</strong> learning opportunities${ui.query?` for “${esc(ui.query)}”`:''}</span><label>Sort <select id="search-sort" aria-label="Sort search results">${options([['relevant','Most relevant'],['shortest','Shortest first'],['title','Course title']],ui.filters.sort)}</select></label></div>${result.length?`<div class="course-grid">${result.slice(ui.page*size,(ui.page+1)*size).map(c=>courseCard(c)).join('')}</div><div class="pagination">${button('Previous','page',`data-page="${ui.page-1}" ${ui.page===0?'disabled':''}`,'small')}<span>Page ${ui.page+1} of ${pages}</span>${button('Next','page',`data-page="${ui.page+1}" ${ui.page===pages-1?'disabled':''}`,'small')}</div>`:`<div class="empty">${icon('search')}<h3>No matches yet</h3><p>Try a broader topic or clear a filter. You can search by course name, provider, tool, or learning need.</p>${button('Clear search and filters','reset-search')}</div>`}`;}
function planView(){
  const p=progress(B,learner),map=courseMap(B),entries=Object.entries(learner.items).sort((a,b)=>a[1].order-b[1].order);
  const filtered=entries.filter(([,i])=>ui.planTab==='all'||(ui.planTab==='active'?['planned','in-progress'].includes(i.status):i.status===ui.planTab));
  const tabs=[['active','My path'],['saved','Saved for later'],['completed','Completed'],['deferred','Deferred'],['all','All learning']];
  return `<div class="print-only print-header"><h1>${esc(learner.profile.name||'My')} AI learning path</h1><p>${esc(nice(groupFor(B,learner).name))} · Catalog ${esc(B.catalogue.version)}</p><p>Course completion is self-reported. Coverage describes syllabus evidence, not demonstrated competence.</p></div>${intro('Your path. At your pace.','Turn good intentions into a learning plan you can follow.',button(`${icon('plus')} Find training`,'nav','data-view="explore"'))}<div class="main-grid"><div class="main-column">${pathSummary(learner.profile,false)}<p class="tiny-note" style="margin:12px 0 20px">Courses can support more than one layer; your plan counts each course once.</p><div class="stat-strip"><div><strong>${p.total-p.completed}</strong><span>courses to complete</span></div><div><strong>${formatHours(p.remaining)}${p.unknown?' + ?':''}</strong><span>estimated time remaining</span></div></div><div class="tabs" role="tablist" aria-label="Learning status">${tabs.map(([id,label])=>button(label,'plan-tab',`data-tab="${id}" role="tab" aria-selected="${ui.planTab===id}"`,ui.planTab===id?'active':'')).join('')}</div>${filtered.length?`<div class="plan-list">${filtered.map(([id,item],index)=>planRow(id,item,map.get(id),index,filtered.length)).join('')}</div>`:`<div class="empty">${icon(ui.planTab==='completed'?'flag':'book')}<h3>${ui.planTab==='completed'?'Your completed learning will appear here':ui.planTab==='saved'?'Keep interesting courses for later':'Make your first learning commitment'}</h3><p>${ui.planTab==='saved'?'Use the bookmark on any offering. Saved courses stay separate from your committed plan.':'Choose a recommendation or explore the catalog. Add a course, give it a target date, and take it one step at a time.'}</p>${button('Explore training','nav','data-view="explore"','primary')}</div>`}<div class="actions no-print" style="margin-top:24px">${button(`${icon('download',true)} Export plan CSV`,'plan-csv','','small')}${button(`${icon('book',true)} Print plan`,'print','','small')}${button('Back up progress','backup','','small ghost')}</div></div>${sidePanel()}</div>`;
}
function planRow(id,item,c,index,total){const today=localDate(),overdue=item.dueDate&&item.dueDate<today&&item.status!=='completed',h=c?hoursFor(B,c):null;return `<article class="plan-item"><div class="plan-order"><span>${index+1<10?'0':''}${index+1}</span>${button(icon('up'),'move',`data-id="${esc(id)}" data-direction="-1" ${index===0?'disabled':''} aria-label="Move ${esc(item.title)} earlier"`)}${button(icon('chevron'),'move',`data-id="${esc(id)}" data-direction="1" ${index===total-1?'disabled':''} aria-label="Move ${esc(item.title)} later"`)}</div><div><div class="plan-item-head"><div><div class="provider">${esc(c?.provider||'Archived offering')}</div>${button(esc(c?.title||item.title),'course',`data-id="${esc(id)}"`,'title-button')}</div>${button(icon('close'),'remove',`data-id="${esc(id)}" aria-label="Remove ${esc(item.title)} from my learning"`,'icon-button no-print')}</div><div class="tags">${tag(sources[sourceFor(B,learner,id)],sourceFor(B,learner,id))}${reviewTag(id)}${statusTag(id)}${c?displayTracks(B,learner,c).map(t=>tag(['central','central-role'].includes(sourceFor(B,learner,id))?t:'Supports '+t)).join(''):''}${!c?tag('No longer in this catalog','amber'):''}${c&&unavailable(c)?tag('Not available yet','amber'):''}</div><div class="plan-meta"><span>${icon('clock',true)} ${esc(formatHours(h))}</span>${item.completedOn?`<span>Completed ${esc(item.completedOn)}</span>`:''}${item.dueDate?`<span class="${overdue?'overdue':''}">${overdue?'Past target · ':''}${esc(item.dueDate)}</span>`:''}${item.actualHours!==null?`<span>Actual: ${formatHours(item.actualHours)}</span>`:''}</div>${item.notes?`<p class="tiny-note">${esc(item.notes)}</p>`:''}<div class="plan-item-actions"><label class="inline-label">Status<select data-item-status="${esc(id)}" aria-label="Status for ${esc(item.title)}">${options(STATUSES.map(s=>[s,STATUS_LABELS[s]]),item.status)}</select></label><label class="inline-label">Target<input type="date" data-item-date="${esc(id)}" value="${esc(item.dueDate)}" aria-label="Target date for ${esc(item.title)}"></label><div class="actions">${button('Notes','notes',`data-id="${esc(id)}"`,'small')}${item.status==='completed'?button(`${icon('star',true)} ${learner.feedback.some(f=>f.courseId===id)?'My feedback':'Rate course'}`,'feedback',`data-id="${esc(id)}"`,'subtle small'):c&&!unavailable(c)?button(item.status==='in-progress'?'Mark complete':'Start learning',item.status==='in-progress'?'complete':'start',`data-id="${esc(id)}"`,'small primary'):''}</div></div></div></article>`;}
function profileView(){const p=learner.profile,check=assessment(learner),pending=learner.feedback.filter(f=>f.delivery!=='reported-submitted');return `${intro('Build your four-layer path.','Foundation is included. Choose one AI level, your specialisations, and your tools.')}<div class="main-grid"><div class="main-column"><form id="profile-form"><div class="profile-layers"><section class="panel profile-layer foundation"><div class="layer-heading"><span class="layer-number">01</span><div><h2>Foundation</h2><p>Common knowledge, safe use, and AI risks. Included in every path.</p></div>${tag('Always included')}</div></section><section class="panel profile-layer level"><div class="layer-heading"><span class="layer-number">02</span><div><h2>Choose your target work level</h2><p>The work you are expected to do sets your target. Your starting point only changes the learning order.</p></div></div>${levelOptions(p.level)}${startingGuidance(p)}<div class="profile-assessment"><p>Four practical checks help choose where to begin. They never lower your work target or certify competence.</p>${button('Review my starting point','retake','','subtle small')}</div></section><section class="panel profile-layer specialist"><div class="layer-heading"><span class="layer-number">03</span><div><h2>Choose your roles and responsibilities</h2><p>Select one or more roles, then the work you do within each. Roles are independent of your AI level.</p></div></div>${roleChecks(p)}</section><section class="panel profile-layer tool"><div class="layer-heading"><span class="layer-number">04</span><div><h2>Choose your tools</h2><p>Select one or more tools you use or are preparing to use.</p></div></div>${toolChecks(p)}<p class="tiny-note">Choose tools permitted for your work. Selecting a tool does not grant access.</p></section></div>${scopeEditor(p)}<section class="panel"><div class="panel-title"><h2>Your preferences</h2><p>Changing your path updates suggestions. Your personal plan is preserved.</p></div><label class="field"><span>First name (optional)</span><input name="name" maxlength="80" value="${esc(p.name)}" autocomplete="given-name"></label><label class="field"><span>How often do you work with AI?</span><select name="experience">${options([['new','I am getting started'],['some','I have tried it a few times'],['regular','I use AI regularly']],p.experience)}</select></label><label class="check-line"><input type="checkbox" name="codingReady" ${p.codingReady?'checked':''}> I am comfortable with Python and Git</label><p class="tiny-note">This checks recorded coding prerequisites. No-code builders can still choose L3.</p><label class="field" style="margin-top:20px"><span>Previous learning or experience (optional)</span><textarea name="priorLearning" maxlength="2000">${esc(p.priorLearning)}</textarea></label></section><div class="profile-save"><span>Foundation + one level + specialisations + tools</span><button class="primary" type="submit">Save my path</button></div></form><section class="panel" style="margin-top:24px"><div class="panel-title"><h2>Your data stays with you</h2><p>Progress is saved in this browser. Export a backup before switching devices, clearing browser data, or moving a local HTML file.</p></div><div class="actions">${button(`${icon('download',true)} Download backup`,'backup','','small')}${button(`${icon('upload',true)} Restore backup`,'restore','','small')}${button('Export plan CSV','plan-csv','','small')}${corruptBackup?button('Download original unreadable data','corrupt-backup','','small'):''}</div></section><section class="panel"><div class="panel-title"><h2>Your course feedback</h2><p>${pending.length} saved feedback response${pending.length===1?'':'s'} awaiting submission or confirmation. Opening Forms does not confirm receipt.</p></div>${learner.feedback.length?learner.feedback.map(f=>`<div class="pending-row"><div><strong>${esc(f.courseTitle)}</strong><small style="display:block">${f.usefulness}/5 · ${esc(f.difficulty)} · ${f.delivery==='reported-submitted'?'Submission confirmed by you':f.delivery==='opened'?'Form opened; receipt unverified':'Saved locally'}</small></div>${button('Review','feedback',`data-id="${esc(f.courseId)}"`,'small')}</div>`).join(''):'<p class="muted">Mark a course complete to leave a short rating.</p>'}<div class="actions" style="margin-top:15px">${button('Export feedback JSON','export-feedback','','small')}</div></section></div>${sidePanel()}</div>`;}
function levelOptions(value,compact=false){return `<fieldset class="level-options"><legend class="sr-only">Your AI level</legend>${PATH_LEVELS.map(l=>`<label class="level-option"><input type="radio" name="level" value="${l.level}" ${value===l.level?'checked':''} required><span><strong>${esc(l.name)}</strong><small>${esc(compact?['AI assists with your own tasks.','Supervise agents and check their work.','Build or configure agents and evaluate them.'][l.level-1]:l.description)}</small></span></label>`).join('')}</fieldset>`;}
function roleChecks(p,scope='profile'){
  return `${p.pendingSpecialisms?.length?`<div class="role-migration"><strong>Place your previous shared responsibilities</strong><p>${p.pendingSpecialisms.map(responsibilityName).map(esc).join(' · ')}</p><small>Select Governance, risk, compliance & assurance, Leadership, or both, and check each responsibility below. Its learning stays in your path until you confirm.</small></div>`:''}<div class="role-options" role="group" aria-label="Learning roles">${LEARNING_ROLES.map(r=>`<section class="role-choice"><label class="role-select"><input type="checkbox" name="roles" value="${r.id}" ${p.roles.includes(r.id)?'checked':''} aria-controls="${scope}-role-choices-${r.id}" aria-expanded="${p.roles.includes(r.id)}"><span class="role-number">${r.id}</span><span><strong>${esc(r.name)}</strong><small>${r.packages.length?'Select the responsibilities you need':'Shared AI-risk learning and tool training'}</small></span></label><div class="role-responsibilities" id="${scope}-role-choices-${r.id}" data-role-choices="${r.id}" ${p.roles.includes(r.id)?'':'hidden'}>${r.packages.length?`<p>Choose at least one responsibility</p>${r.packages.map(id=>`<label><input type="checkbox" name="responsibility-${r.id}" value="${id}" ${(p.roleResponsibilities[r.id]||[]).includes(id)?'checked':''}><span>${esc(responsibilityName(id))}${LEARNING_ROLES.filter(r=>r.packages.includes(id)).length>1?'<small>Shared with another role · counted once</small>':''}</span></label>`).join('')}`:'<p>Reuse Foundation’s AI-risk learning and training for your selected tools. No additional specialist responsibility is needed.</p>'}</div></section>`).join('')}</div><div class="activity-questions">${activityQuestions(p)}</div>`;
}
function activityQuestions(p){
  return ACTIVITIES.map(a=>`<label class="field activity-question" ${applicableActivities(p).some(x=>x.id===a.id)?'':'hidden'}><span>${a.id==='automated-judges'?'Do you use automated judges to evaluate AI outputs?':'Do you use AI to perform assurance work?'}</span><select name="activity-${a.id}" ${!p.quickSetup&&applicableActivities(p).some(x=>x.id===a.id)?'required':''}>${options([['',p.quickSetup?'Not specified (optional)':'Choose an answer'],['yes','Yes'],['no','No']],typeof p.activityAnswers[a.id]==='boolean'?(p.activityAnswers[a.id]?'yes':'no'):'')}</select><small>Your answer determines whether ${esc(a.requirement)} is essential. Your role alone does not.</small></label>`).join('');
}
function readRoleChoices(values,base){
  const roles=values.getAll('roles').map(Number),roleResponsibilities=Object.fromEntries(roles.map(id=>[id,values.getAll('responsibility-'+id)])),activityAnswers={...base.activityAnswers};
  for(const a of ACTIVITIES)if(values.has('activity-'+a.id)){
    const answer=values.get('activity-'+a.id);if(answer==='yes'||answer==='no')activityAnswers[a.id]=answer==='yes';else delete activityAnswers[a.id];
  }
  const placed=new Set(Object.values(roleResponsibilities).flat()),pendingSpecialisms=(base.pendingSpecialisms||[]).filter(id=>!placed.has(id));
  return syncRoleProfile({...base,pathVersion:4,roles,roleResponsibilities,pendingSpecialisms,activityAnswers});
}
function toolChecks(p){
  const list=[...new Set([...toolsList,...p.tools])];
  return `<div class="tool-options">${list.map((tool,i)=>`<section class="tool-choice"><label class="tool-select"><input type="checkbox" name="tools" value="${esc(tool)}" ${p.tools.includes(tool)?'checked':''}><strong>${esc(tool)}</strong></label><div class="tool-purpose" ${p.tools.includes(tool)?'':'hidden'}><p>What will you do with this tool? ${p.quickSetup?'Optional — refine your suggestions.':'Choose all that apply.'}</p>${TOOL_USES.map(use=>`<label><input type="checkbox" name="tool-use-${i}" value="${use.id}" ${(p.toolUses?.[tool]||[]).includes(use.id)?'checked':''}><span>${esc(use.name)}<small>${esc(use.description)}</small></span></label>`).join('')}<input type="hidden" name="tool-name-${i}" value="${esc(tool)}"></div></section>`).join('')}</div>`;
}
function readToolChoices(values){
  const tools=values.getAll('tools'),toolUses={};
  for(const [key,tool] of values)if(key.startsWith('tool-name-')&&tools.includes(tool))toolUses[tool]=values.getAll('tool-use-'+key.slice(10));
  return {tools,toolUses};
}
function startingGuidance(p){
  const result=startingPoint(p),answered=CHECKS.some(q=>Number.isInteger(p.answers[q.id]));
  return `<div class="starting-guidance"><div><span class="eyebrow">TARGET WORK</span><strong>L${p.level} · ${esc(PATH_LEVELS[p.level-1].name.split(' · ')[1])}</strong></div><div><span class="eyebrow">WHERE TO BEGIN</span><strong>${answered||p.quickSetup?`L${result.level} practice`:'Foundation and L1 practice'}</strong><p>${result.level<p.level?`Build toward L${p.level} through ${Array.from({length:p.level-result.level+1},(_,i)=>'L'+(result.level+i)).join(' → ')}. All target outcomes remain in your path.`:'Foundation and earlier-level practice remain available where needed.'}</p></div>${p.targetReview?`<p class="target-review">Your earlier work goal was L${p.targetReview.previousGoal}; your confirmed level was L${p.targetReview.confirmedLevel}. Review your target in My profile. Your existing plan is preserved.</p>`:''}</div>`;
}
function scopeEditor(p){
  const saved=p.centralScope,diff=scopeDifference(B,p),groups=B.scenario.cohorts;
  const choices=[['','Standard model outcomes'],...groups.map(g=>[g.id,nice(g.name)])];
  if(saved&&!groups.some(g=>g.id===saved.groupId))choices.push([saved.groupId,nice(saved.groupName)+' (saved scope)']);
  return `<details class="panel central-scope-editor" ${saved?'open':''}><summary>Central learning profile (optional)</summary><p class="tiny-note">Use this if your learning team assigned a specific central profile. Its outcome additions and removals apply to your path; recommendations from other profiles do not change your scope.</p><label class="field"><span>Assigned central profile</span><select name="central-profile">${options(choices,saved?.groupId||'')}</select></label><div class="scope-preview">${scopeSummary(saved)}</div>${diff?`<div class="notice info"><span>${diff.missing?'The saved source is not in the active central plan.':'The central outcome choices have changed.'} Your saved scope is retained. ${button('Review outcome changes','scope-review','','banner-link')}</span></div>`:''}<small>Saving a different profile replaces only these scope choices. Your courses and history stay intact.</small></details>`;
}
function scopeSummary(scope){
  return scope?`<p class="tiny-note"><strong>${esc(nice(scope.groupName))}</strong><br>Added outcomes: ${scope.added.map(esc).join(', ')||'None'}<br>Removed outcomes: ${scope.removed.map(esc).join(', ')||'None'}</p>`:'<p class="tiny-note">Use the model outcomes for your level and selected responsibilities.</p>';
}
function reviewScope(){
  const diff=scopeDifference(B,learner.profile);if(!diff)return;
  showDialog('Review central outcome choices',`<p>These changes affect target requirements and suggestions. Your learning items, completion records and feedback remain intact.</p><h3>Your saved scope</h3>${scopeSummary(diff.saved)}<h3>Latest central scope</h3>${diff.current?scopeSummary(diff.current):'<p>The original central profile is unavailable. Keep the saved scope, or choose a replacement in My profile.</p>'}`,`${button('Keep saved scope','close')}${diff.current?button('Use latest outcome choices','scope-update','','primary'):button('Open My profile','dialog-profile','','primary')}`);
}
function openCourse(id){
  const c=courseMap(B).get(id);ui.dialog={type:'course',id};
  if(!c){const i=learner.items[id];showDialog('An archived learning item',`<p>${esc(i?.title||id)}</p><p>This item is no longer in the current catalog. Your history and notes have been retained.</p>`,button('Close','close'));return;}
  const reqs=requirementsFor(B,learner),contributes=reqs.filter(r=>(c.scores[r.id]?.score||0)>0),suggestion=currentRecommendations.find(x=>x.course.id===id),source=sourceFor(B,learner,id,!!suggestion),reason=['central','central-role'].includes(source)?centralReason(B,learner,c):suggestion?.reason||'Explore this offering and decide whether its content, prerequisites, and time fit your work.',item=learner.items[id];
  const details=`<div class="tags">${tag(sources[source],source)}${reviewTag(id)}${statusTag(id)}${displayTracks(B,learner,c).map(t=>tag(t)).join('')}</div><p class="detail-copy">${esc(c.description)}</p><div class="notice info">${icon('spark')}<span>${esc(reason)}</span></div>${unavailable(c)?`<div class="notice">${icon('info')}<span>${esc(unavailable(c))}. Save for later while delivery is being prepared.</span></div>`:''}<div class="details-grid"><div><strong>Provider</strong>${esc(c.provider)}</div><div><strong>Learning time</strong>${formatHours(hoursFor(B,c))}<small style="display:block">${esc(c.duration)}${Object.hasOwn(B.scenario.overrides,id)?' · central planner estimate':''}</small></div><div><strong>Format & access</strong>${esc(c.format||c.type)}<small style="display:block">Cost: ${esc(c.cost||'Confirm with provider')}</small></div><div><strong>Source evidence</strong>${esc(c.evidence)}<small style="display:block">${esc(c.id)} · ${esc(B.catalogue.assessmentDate)}</small></div></div><div class="detail-section"><h3>Prerequisites, fit, and limitations</h3><p class="detail-copy">${esc(c.limitations||'Check the provider’s prerequisites and your approved access before starting. Catalog suitability does not establish professional readiness.')}</p>${external(c.url,'View course with provider')}</div><details><summary class="details-toggle">Recorded learning evidence (${contributes.length} applicable outcomes)</summary>${contributes.length?contributes.map(r=>`<div class="evidence-row"><strong>${esc(r.id)} · ${esc(r.title)}</strong> ${tag(`${c.scores[r.id].score}/3`)}${r.core?tag('Essential','amber'):''}<small>${esc(c.scores[r.id].evidence||'Recorded assessment; see the catalog source.')}</small></div>`).join(''):'<p class="tiny-note">No requirement-level coverage is recorded for your current profile. This does not imply the course is poor; it may be unassessed or serve different needs.</p>'}</details><div class="actions" style="margin-top:20px">${button(`${icon('compare',true)} ${ui.compared.includes(id)?'Remove from comparison':'Compare this offering'}`,'compare-toggle',`data-id="${esc(id)}"`,'small')}${item?button('Edit notes & time','notes',`data-id="${esc(id)}"`,'small'):''}${item?.status==='completed'?button('Rate this course','feedback',`data-id="${esc(id)}"`,'small'):''}</div>`;
  showDialog(c.title,details,`<small>${item?'Your selection is saved in this browser.':'Adding a course is a personal commitment.'}</small><div class="actions">${button(icon('bookmark',true)+' Save for later','save-course',`data-id="${esc(id)}"`,'small')}${isCommitted(id)?button('Open my learning','dialog-plan','','primary'):unavailable(c)?'':button(`${icon('plus',true)} Add to my plan`,'add',`data-id="${esc(id)}" data-source="${source}"`,'primary')}</div>`);
}
function whyDialog(id,suggested,layerId){const c=courseMap(B).get(id);if(!c)return;const source=sourceFor(B,learner,id,suggested),r=['central','central-role'].includes(source)?centralReason(B,learner,c):flattenLayers(currentLayers).find(l=>l.id===layerId)?.suggestions.find(x=>x.course.id===id)?.reason||currentRecommendations.find(x=>x.course.id===id)?.reason||'This is an offering from the full catalog. Check its course details and fit before choosing it.';showDialog('Why this course?',`<h3>${esc(c.title)}</h3><div class="tags">${tag(sources[source],source)}</div><p>${esc(r)}</p><p class="tiny-note">Each layer draws on matching selections from the central training builder. Personalised suggestions use recorded teaching, your tools, starting-point answers, and time. They do not change the central pathway.</p>`,`${button('Close','close')} ${button('View course','course',`data-id="${esc(id)}"`,'primary')}`);}
function acceptPath(){const courses=centralItems(B,learner).filter(c=>!unavailable(c)&&!learner.items[c.id]);showDialog('Review central recommendations',`<p>Review the courses below. Only the checked courses will be added to your personal plan. Existing selections and completed courses are preserved.</p>${B.scenario.status==='Draft'?'<div class="notice">The central pathway is currently a draft. These are planning suggestions, not mandatory assignments.</div>':''}${courses.length?`<div class="scrollable">${courses.map(c=>`<label class="radio-option"><input type="checkbox" name="accept-course" value="${esc(c.id)}" ${sourceFor(B,learner,c.id)==='central-role'?'':'checked'}><span><strong>${esc(c.title)}</strong><small style="display:block">${esc(c.provider)} · ${formatHours(hoursFor(B,c))}</small>${tag(sources[sourceFor(B,learner,c.id)],sourceFor(B,learner,c.id))}${reviewTag(c.id)}${sourceFor(B,learner,c.id)==='central-role'?`<small style="display:block">${esc(centralReason(B,learner,c))}</small>`:''}</span></label>`).join('')}</div>`:'<p>You already have all the available central recommendations in your learning collection. Review saved or deferred items in My learning.</p>'}`,`<small>${courses.length} new available offering${courses.length===1?'':'s'}</small><div class="actions">${button('Cancel','close')}${courses.length?button('Add selected to my plan','accept-path-confirm','','primary'):button('Open my learning','dialog-plan','','primary')}</div>`);}
function needDialog(trackId,needId){const cv=coverage(B,learner,ui.coverageMode),track=cv.rows.find(r=>r.id===trackId),need=track?.needs.find(n=>n.id===needId);if(!need)return;showDialog(need.title,`<div class="tags">${tag(track.name)}${tag(need.unassessed?'No assessed learning selected':need.band)}${tag(`${Math.round(need.coverage*100)}% syllabus coverage`)}</div><p class="tiny-note">Each outcome uses the highest recorded course score, with no double counting. A need is Strong at 70% with no essential outcome at zero; Full means every applicable outcome scores 3.</p>${need.rows.map(r=>`<div class="evidence-row"><strong>${esc(r.id)} · ${esc(r.title)}</strong> ${tag(`${r.score}/3`)} ${r.core?tag('Essential','amber'):''}<p style="margin:5px 0">${esc(r.description)}</p><small>${r.witnesses.filter(c=>(c.scores[r.id]?.score||0)>0).map(c=>esc(c.title)).join(' · ')||'No teaching evidenced in this selection.'}</small></div>`).join('')}`,`<small>Coverage is not a competence sign-off.</small>${button('Find relevant training','need-search',`data-need="${esc(needId)}"`,'primary')}`);}
function compareDialog(){const map=courseMap(B),courses=ui.compared.map(id=>map.get(id)).filter(Boolean);if(!courses.length)return;const rows=[['Provider',c=>esc(c.provider)],['Time',c=>formatHours(hoursFor(B,c))],['Source',c=>esc(sources[sourceFor(B,learner,c.id,!!currentRecommendations.find(x=>x.course.id===c.id))])],['My choice',c=>esc(STATUS_LABELS[planState(c.id)]||'Not selected')],['Tracks',c=>esc(displayTracks(B,learner,c).join(', ')||'Other learning')],['Content',c=>esc(c.description)],['Fit & limitations',c=>esc(c.limitations||'Check provider prerequisites.')],['Evidence',c=>esc(c.evidence)],['Access / cost',c=>esc(c.cost||'Confirm with provider')],['Next step',c=>isCommitted(c.id)?'In my plan':unavailable(c)?'Awaiting availability':button('Add to my plan','add',`data-id="${esc(c.id)}"`,'small primary')]];showDialog('Compare your options',`<div class="table-wrap"><table class="compare-table"><thead><tr><th>Offering</th>${courses.map(c=>`<th>${esc(c.title)}</th>`).join('')}</tr></thead><tbody>${rows.map(([name,fn])=>`<tr><th>${name}</th>${courses.map(c=>`<td>${fn(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,button('Close','close'),true);ui.dialog={type:'compare'};}
function notesDialog(id){const item=learner.items[id];if(!item)return;ui.dialog={type:'notes',id};showDialog('Make room for this course',`<h3>${esc(item.title)}</h3><form id="notes-form"><div class="form-grid"><label class="field"><span>Target completion date</span><input name="dueDate" type="date" value="${esc(item.dueDate)}"></label><label class="field"><span>Actual time spent (hours)</span><input name="actualHours" type="number" min="0" max="10000" step="0.25" value="${item.actualHours??''}" placeholder="Leave blank if unknown"></label></div><label class="field"><span>Notes for yourself</span><textarea name="notes" maxlength="10000" placeholder="Why this matters, a useful takeaway, or your next practical step…">${esc(item.notes)}</textarea></label>${item.status==='completed'?`<label class="field"><span>Completion date</span><input name="completedOn" type="date" required value="${esc(item.completedOn||localDate())}"></label>`:''}</form>`,`<small>Personal notes are included in your backup.</small>${button('Save changes','notes-save',`data-id="${esc(id)}"`,'primary')}`);}
function startLearning(id){const c=courseMap(B).get(id);if(!c)return;setStatus(B,learner,id,'in-progress');save();render();showDialog('Ready when you are',`<h3>${esc(c.title)}</h3><p>Your course is now in progress. Open the provider’s page to enrol or continue learning.</p><div class="actions">${external(c.url,'Open course')}</div><p class="tiny-note">Provider access and any enrolment cost are handled outside this app. Mark the course complete when you finish.</p>`,button('Back to my plan','dialog-plan','','primary'));}
function feedbackDialog(id){const c=courseMap(B).get(id),item=learner.items[id];const f=learner.feedback.find(x=>x.courseId===id);if(item?.status!=='completed'){if(f){showDialog('Your saved course feedback',`<h3>${esc(f.courseTitle)}</h3><p>${f.usefulness}/5 · ${esc(f.difficulty)} · ${formatHours(f.actualHours)}</p><p>${esc(f.comment||'No comment provided.')}</p><p class="tiny-note">Recorded for ${esc(f.groupName)} · Catalog ${esc(f.catalogueVersion)}. To edit this rating, record the course as completed in My learning.</p>`,`${button('Close','close')}${formsTemplate()?button('Continue to Forms','feedback-resend',`data-id="${esc(f.id)}"`,'primary'):''}`);return;}throw Error('Mark this course complete before rating it.');}ui.dialog={type:'feedback',id};const configured=!!(formsTemplate());showDialog('How was the learning?',`<h3>${esc(c?.title||item.title)}</h3><p class="muted">A few quick answers help improve future suggestions.</p><form id="feedback-form"><div class="field"><span>How useful was this course for your work?</span><div class="rating-options">${[1,2,3,4,5].map(n=>`<label><input type="radio" name="usefulness" value="${n}" ${f?.usefulness===n?'checked':''} required aria-label="Usefulness ${n} out of 5"><span>${n}</span></label>`).join('')}</div><div class="rating-labels"><span>Not useful</span><span>Very useful</span></div></div><div class="form-grid"><label class="field"><span>How did the difficulty feel?</span><select name="difficulty" required>${options([['','Choose one'],'Too basic','About right','Too advanced'],f?.difficulty||'')}</select></label><label class="field"><span>Actual learning time (hours, optional)</span><input type="number" name="actualHours" min="0" max="10000" step="0.25" value="${f?.actualHours??item.actualHours??''}" placeholder="e.g. 1.5"></label></div><label class="field"><span>Anything to share? (optional)</span><textarea name="comment" maxlength="1200" placeholder="What helped, what was missing, or who would benefit…">${esc(f?.comment||'')}</textarea></label></form><div class="notice ${configured?'info':''}">${icon('info')}<span>${configured?'Your course details and answers will be prefilled in Microsoft Forms. Review them and press Submit there.':'Central feedback is not connected yet. Save your rating here; it can be sent later or exported for an administrator.'}</span></div>${f?.delivery==='opened'?`<div class="actions">${button('I submitted this in Forms','feedback-confirm',`data-id="${esc(f.id)}"`,'small')}</div><p class="tiny-note">This records your confirmation, not a verified receipt from Microsoft.</p>`:''}${f?.delivery==='reported-submitted'?'<p class="tiny-note">You previously confirmed submission. Editing creates an updated local response; submit it again to update central feedback.</p>':''}`,`<small>Course and group details are filled automatically.</small><div class="actions">${button('Save locally','feedback-save',`data-id="${esc(id)}"`)}${configured?button('Continue to Forms','feedback-send',`data-id="${esc(id)}"`,'primary'):''}</div>`);}
function saveFeedback(id){const form=$('#feedback-form');if(!form.reportValidity())return null;const values=new FormData(form),g=groupFor(B,learner),item=learner.items[id],previous=learner.feedback.find(f=>f.courseId===id),c=courseMap(B).get(id);const f=validateFeedback({id:previous?.id||uid(),courseId:id,courseTitle:c?.title||item.title,groupId:previous?.groupId||item.completionContext?.groupId||g.id,groupName:previous?.groupName||nice(item.completionContext?.groupName||g.name),catalogueVersion:previous?.catalogueVersion||item.completionContext?.catalogueVersion||B.catalogue.version,completedOn:item.completedOn||'',usefulness:Number(values.get('usefulness')),difficulty:values.get('difficulty'),actualHours:values.get('actualHours')===''?null:Number(values.get('actualHours')),comment:values.get('comment').trim(),created:previous?.created||new Date().toISOString(),updated:new Date().toISOString(),delivery:'saved'});learner.feedback=learner.feedback.filter(x=>x.courseId!==id);learner.feedback.push(f);item.actualHours=f.actualHours;save();return f;}
function openForms(f){const url=feedbackUrl(formsTemplate(),f);f.delivery='opened';save();showDialog('Your feedback is ready',`<p>All known course details and your answers are filled in. Open Microsoft Forms, review the answers, and press <strong>Submit</strong>.</p><p><a class="primary-link" style="display:inline-flex;gap:8px;align-items:center;padding:12px 18px;border-radius:9px" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open prefilled Microsoft Form ${icon('external',true)}</a></p><p class="tiny-note">You may need to sign in with your work account. Opening the link does not confirm that the form was submitted.</p>`,`<small>Your local copy is saved.</small><div class="actions">${button('I’ll submit later','close')}${button('I submitted the form','feedback-confirm',`data-id="${esc(f.id)}"`,'primary')}</div>`);}
function showQuickSetup(){
  const p=learner.profile,tools=[...new Set([...toolsList,...p.tools])];
  const body=`<p class="muted">Three quick choices, then you’re ready. You can change them later.</p><form id="quick-setup-form">
    <fieldset class="quick-section"><legend>1. What is your AI level?</legend>${levelOptions(learner.onboarding?p.level:null,true)}</fieldset>
    <fieldset class="quick-section"><legend>2. What are your responsibilities?</legend><p class="tiny-note">Choose one or more broad areas.</p><div class="quick-choices">${LEARNING_ROLES.map(r=>`<label><input type="checkbox" name="roles" value="${r.id}" ${p.roles.includes(r.id)?'checked':''}><span>${esc(r.name)}</span></label>`).join('')}</div></fieldset>
    <fieldset class="quick-section"><legend>3. Which tools do you plan to use?</legend><p class="tiny-note">Choose one or more.</p><div class="quick-choices quick-tools">${tools.map(tool=>`<label><input type="checkbox" name="tools" value="${esc(tool)}" ${p.tools.includes(tool)?'checked':''}><span>${esc(tool)}</span></label>`).join('')}</div></fieldset>
    <label class="check-line quick-coding"><input type="checkbox" name="codingReady" ${p.codingReady?'checked':''}> I am comfortable with Python and Git (optional)</label>
    <p class="tiny-note">Foundation is included. L3 also includes no-code and low-code work.</p>
  </form>`;
  showDialog('Set up your learning path.',body,`<small>You can refine your path later.</small><div class="actions">${button('Browse first','close')}<button type="submit" form="quick-setup-form" class="primary">Show my learning path</button></div>`);
  $('#dialog').classList.add('quick-setup');ui.dialog={type:'quick-setup'};
}
function saveQuickSetup(form){
  if(!form.reportValidity())return;
  const values=new FormData(form);
  learner.profile=quickPathProfile(learner.profile,{level:Number(values.get('level')),roles:values.getAll('roles').map(Number),tools:values.getAll('tools'),codingReady:values.has('codingReady')});
  learner.onboarding=true;closeDialog();refreshAfterChange();navigate('for-you');toast('Your path is ready. Choose the courses you want to do.');
}
function showStartingChecks(){
  showDialog('Review your starting point.',`<p class="muted">These optional checks help sequence your learning. Your selected work level stays the same.</p><form id="starting-checks-form">${CHECKS.map((q,i)=>`<fieldset class="question"><legend>${i+1}. ${esc(q.title)}</legend>${q.options.map((o,n)=>`<label class="radio-option"><input type="radio" name="${q.id}" value="${n}" ${learner.profile.answers[q.id]===n?'checked':''} required><span>${esc(o)}</span></label>`).join('')}</fieldset>`).join('')}</form>`,`${button('Cancel','close')}<button type="submit" form="starting-checks-form" class="primary">Save starting point</button>`);
}
function reviewUpdate(){const d=updateDifference(B,learner),map=courseMap(B);showDialog('Review central pathway changes',`<p>Your personal selections, dates, feedback, and completion history have been preserved.</p>${d.missingGroup?'<div class="notice">Your previous group is unavailable. Choose a current learning group in My profile.</div>':''}<h3>Central suggestions you have not selected (${d.added.length})</h3>${d.added.map(id=>`<p class="tiny-note">${esc(map.get(id)?.title||id)}</p>`).join('')||'<p class="tiny-note">None.</p>'}<h3 style="margin-top:20px">Selected courses no longer suggested centrally (${d.removed.length})</h3>${d.removed.map(id=>`<p class="tiny-note">${esc(map.get(id)?.title||learner.items[id]?.title||id)} — retained in your plan.</p>`).join('')||'<p class="tiny-note">None.</p>'}${d.unresolved.length?`<h3 style="margin-top:20px">Archived items</h3>${d.unresolved.map(id=>`<p class="tiny-note">${esc(learner.items[id]?.title||id)} — not in this catalog; history retained.</p>`).join('')}`:''}<p class="tiny-note">Changes to course content or evidence are reflected in the current catalog. Confirm your selections remain suitable; this review does not add or remove courses.</p>`,`${button('My profile','dialog-profile')} ${button('Keep my plan & acknowledge','acknowledge-update','','primary')}`);}
function adminView(){const configured=formsTemplate();return `${intro('Keep the learning connected.','Local administrator tools for publishing recommendations and connecting course feedback.')}<div class="notice info">${icon('info')}<span>These tools affect this browser or create files for publication. They do not write to the shared catalog, Forms, or GitHub. This is not an access-controlled administration service.</span></div><div class="panel"><div class="panel-title"><h2>Central learning recommendations</h2><p>${esc(nice(B.scenario.name))} · ${esc(B.scenario.status)} · ${B.scenario.cohorts.length} learning groups</p></div><p class="detail-copy">Import a current scenario JSON exported by the training builder to preview it here. Publish the same file using the build command in the administrator guide. Only current catalog and model versions are accepted.</p><div class="actions">${button('Import central plan JSON','import-central','','small')}${button('Export active central plan','export-central','','small')}${centralOverride?button('Return to bundled plan','reset-central','','small'):''}</div></div><div class="panel"><div class="panel-title"><h2>Microsoft Forms connection</h2><p>${configured?'A prefilled link template is configured. Test it with a real form before distribution.':'Not connected. Learners can save feedback locally until you connect a form.'}</p></div><p class="detail-copy">Create one form with the text questions below. Use <strong>Get pre-filled URL</strong>, fill each answer with its matching placeholder, and paste the full generated link here. Text questions avoid mismatches between choice labels and prefilled answers.</p><details><summary class="details-toggle">Form fields and setup instructions</summary><div class="config-fields">${FEEDBACK_FIELDS.map(k=>`<div><span>Question title: <strong>${k}</strong></span><code>{{${k}}}</code></div>`).join('')}</div><p class="tiny-note">Use these exact question titles for feedback import. Allow multiple responses so a person can review more than one course. Use your organisation’s desired sign-in/name-recording settings. Prefilled fields are visible and editable. Do not branch around them. The app records user-reported submission, not an automatic receipt.</p><p class="tiny-note">COMMENT and ACTUAL_HOURS should be optional. All values are filled from the learner’s course and feedback. Do not enter real personal data when generating the template.</p></details><label class="field"><span>Full prefilled URL template</span><textarea id="forms-template" rows="4" placeholder="https://forms.office.com/Pages/ResponsePage.aspx?…">${esc(configured)}</textarea></label><div class="actions">${button('Save connection on this browser','forms-save','','primary small')}${button('Test prefilled link','forms-test','','small')}${button('Export publishing configuration','export-config','','small')}${button('Disconnect locally','forms-clear','','small ghost')}</div><p class="tiny-note">Exported configuration can be used with the build script to connect the form for everyone. A local setting is not automatically shared.</p></div><div class="panel"><div class="panel-title"><h2>Review learner feedback</h2><p>Import central Forms responses as CSV, or exported learner feedback as JSON. Use the included converter for Forms Excel (.xlsx) exports.</p></div><div class="actions">${button('Import feedback CSV / JSON','import-feedback','','primary small')}${button('Load this browser’s feedback','load-local-feedback','','small')}${adminFeedback.length?button('Clear imported responses','clear-admin-feedback','','small'):''}</div><div id="feedback-review">${adminFeedback.length?feedbackReview():`<div class="empty" style="margin-top:20px;padding:28px"><h3>Look for patterns, then review</h3><p>Compare usefulness, difficulty, and actual time by course, learning group, and catalog version. Individual comments stay out of published summaries.</p></div>`}</div></div>`;}
function feedbackReview(){const summary=summariseFeedback(adminFeedback,B);return `<p class="tiny-note">${summary.responses.length} unique responses. Re-importing the same response ID replaces it. Small samples are shown for review but do not influence suggestions.</p><div class="table-wrap" style="margin:17px 0"><table class="data-table"><thead><tr><th>Course / group</th><th>Responses</th><th>Useful</th><th>Difficulty</th><th>Actual / estimated time</th><th>Review</th></tr></thead><tbody>${summary.groups.map((g,index)=>`<tr><td><strong>${esc(g.courseTitle)}</strong><small style="display:block">${esc(g.groupName)}<br>Catalog ${esc(g.catalogueVersion)}</small></td><td>${g.count}${g.count<5?'<small style="display:block">Small sample</small>':''}</td><td>${g.usefulness.toFixed(1)}/5</td><td>${g.tooAdvanced} too advanced<br>${g.tooBasic} too basic</td><td>${formatHours(g.medianHours)}<br><small>Estimated: ${formatHours(g.estimatedHours)}</small></td><td>${button('Comments','feedback-comments',`data-index="${index}"`,'small')}</td></tr>`).join('')}</tbody></table></div><div class="notice">${icon('info')}<span>Ratings do not change syllabus scores or central assignments. Review course suitability before publishing. Only reviews for the current catalog should inform the next release.</span></div><label class="check-line"><input id="feedback-reviewed" type="checkbox"> I have reviewed these responses for suitability and duplicate submissions.</label><div class="actions" style="margin-top:15px">${button('Export reviewed aggregate','export-reviewed-feedback','','primary small')}</div><p class="tiny-note">Published aggregates contain course IDs, response counts, and average usefulness only. At least five responses are required for a small ranking adjustment to optional suggestions. Central recommendations and personal commitments are preserved.</p>`;}
function download(filename,body,mime='application/json'){const url=URL.createObjectURL(new Blob([body],{type:mime}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(`Download prepared: ${filename}`);}
function pickFile(purpose){filePurpose=purpose;$('#file-input').accept=purpose==='feedback'?'.json,.csv':'.json';$('#file-input').value='';$('#file-input').click();}
function fingerprint(value){let h=2166136261;for(const c of JSON.stringify(value)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return 'local-'+(h>>>0).toString(16);}
async function importFile(file){if(!file)return;if(file.size>30*1024*1024)throw Error('This file is too large. Use a backup, a current scenario, or a feedback export under 30 MB.');const text=await file.text();if(filePurpose==='backup'){const incoming=validateBackup(JSON.parse(text));showDialog('Restore this learning backup?',`<p>Restore <strong>${esc(incoming.profile.name||'this learner’s')}</strong> profile with ${Object.keys(incoming.items).length} learning items and ${incoming.feedback.length} feedback responses?</p><p>This replaces this browser’s personal plan. Download a backup first if you want to preserve the current one.</p>`,`${button('Back up current plan','backup')} ${button('Restore this backup','restore-confirm','','primary')}`);ui.pendingBackup=incoming;return;}
  if(filePurpose==='central'){const s=validateCentralScenario(JSON.parse(text),B);showDialog('Preview this central pathway?',`<p><strong>${esc(nice(s.name))}</strong><br>${s.cohorts.length} learning groups · ${esc(s.status)}</p><p>Your personal selections and completion history will stay in place. This import affects this browser only.</p>`,`${button('Cancel','close')} ${button('Use this pathway locally','central-confirm','','primary')}`);ui.pendingCentral=s;return;}
  if(filePurpose==='feedback'){const parsed=file.name.toLowerCase().endsWith('.csv')?feedbackFromRows(parseCSV(text)):JSON.parse(text);const responses=Array.isArray(parsed)?parsed:parsed.feedback||parsed.responses;if(!Array.isArray(responses))throw Error('Use a feedback JSON export or a Forms CSV with the documented column titles.');const summary=summariseFeedback([...adminFeedback,...responses],B);adminFeedback=summary.responses;render();toast(`Loaded ${adminFeedback.length} unique feedback responses.`);}
}
function refreshAfterChange(){save();render();}
document.addEventListener('click',async event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,id=el.dataset.id;
  try{
    if(action==='scope-review'){reviewScope();return;}
    if(action==='scope-update'){const diff=scopeDifference(B,learner.profile);if(diff?.current){learner.history.push({date:new Date().toISOString(),event:'Reviewed central outcome scope',previous:structuredClone(learner.profile.centralScope),current:structuredClone(diff.current)});learner.profile.centralScope=diff.current;}closeDialog();refreshAfterChange();return;}
    if(action==='close'){closeDialog();return;}
    if(action==='nav'){navigate(el.dataset.view);return;}
    if(action==='dialog-plan'){navigate('plan');return;}
    if(action==='dialog-profile'){navigate('profile');return;}
    if(action==='course'){openCourse(id);return;}
    if(action==='why'){whyDialog(id,el.dataset.suggested==='true',el.dataset.layer);return;}
    if(action==='save-course'){
      const state=planState(id);if(isCommitted(id)||state==='deferred'){toast('This offering is already in My learning. Change its status there.');return;}
      if(state==='saved')delete learner.items[id];else setStatus(B,learner,id,'saved',sourceFor(B,learner,id,!!currentRecommendations.find(x=>x.course.id===id)));
      const dialog=ui.dialog;refreshAfterChange();if(dialog?.type==='course')openCourse(id);toast(state==='saved'?'Removed from saved courses.':'Saved for later.');return;
    }
    if(action==='add'){setStatus(B,learner,id,'planned',el.dataset.source||sourceFor(B,learner,id,!!currentRecommendations.find(x=>x.course.id===id)));const dialog=ui.dialog;refreshAfterChange();if(dialog?.type==='course')openCourse(id);if(dialog?.type==='compare')compareDialog();toast('Added to your personal learning plan.');return;}
    if(action==='accept-path'){acceptPath();return;}
    if(action==='accept-path-confirm'){const ids=[...document.querySelectorAll('input[name="accept-course"]:checked')].map(x=>x.value);for(const id of ids)setStatus(B,learner,id,'planned',sourceFor(B,learner,id));closeDialog();refreshAfterChange();navigate('plan');toast(`${ids.length} courses added to your plan.`);return;}
    if(action==='layer-jump'){const target=$('#layer-'+el.dataset.kind);if(target){target.scrollIntoView({block:'start',behavior:'instant'});target.querySelector('h2')?.focus?.();}return;}
    if(action==='layer-search'){ui.filters={sort:'relevant',layer:el.dataset.layer};ui.query='';ui.page=0;navigate('explore');return;}
    if(action==='toggle-central'){ui.showCentralAll=!ui.showCentralAll;render();return;}
    if(action==='filter'){ui.filters[el.dataset.filter]=!ui.filters[el.dataset.filter];ui.page=0;render();return;}
    if(action==='filters-toggle'){ui.showFilters=!ui.showFilters;render();return;}
    if(action==='clear-filters'||action==='reset-search'){ui.filters={sort:'relevant'};if(action==='reset-search')ui.query='';ui.page=0;render();return;}
    if(action==='clear-need'){delete ui.filters.need;ui.page=0;render();return;}
    if(action==='page'){ui.page=Number(el.dataset.page);$('#explore-results').innerHTML=exploreResults();$('#course-search').scrollIntoView({block:'start',behavior:'instant'});return;}
    if(action==='plan-tab'){ui.planTab=el.dataset.tab;render();return;}
    if(action==='move'){const visible=Object.entries(learner.items).filter(([,i])=>ui.planTab==='all'||(ui.planTab==='active'?['planned','in-progress'].includes(i.status):i.status===ui.planTab)).sort((a,b)=>a[1].order-b[1].order);const index=visible.findIndex(([key])=>key===id),other=visible[index+Number(el.dataset.direction)];if(other){const orders=Object.values(learner.items).sort((a,b)=>a.order-b.order);orders.forEach((x,i)=>x.order=i);[learner.items[id].order,other[1].order]=[other[1].order,learner.items[id].order];refreshAfterChange();}return;}
    if(action==='remove'){showDialog('Remove from your learning?',`<p>${esc(learner.items[id]?.title)}</p><p>This removes the personal commitment and its completion record. The course remains in the catalog, and existing feedback is retained.</p>`,`${button('Keep it','close')} ${button('Remove from my learning','remove-confirm',`data-id="${esc(id)}"`,'primary')}`);return;}
    if(action==='remove-confirm'){delete learner.items[id];closeDialog();refreshAfterChange();return;}
    if(action==='start'){startLearning(id);return;}
    if(action==='complete'){setStatus(B,learner,id,'completed');refreshAfterChange();feedbackDialog(id);return;}
    if(action==='notes'){notesDialog(id);return;}
    if(action==='notes-save'){const f=$('#notes-form');if(!f.reportValidity())return;const v=new FormData(f),item=learner.items[id];item.dueDate=v.get('dueDate');item.notes=v.get('notes').trim();item.actualHours=v.get('actualHours')===''?null:Number(v.get('actualHours'));if(item.status==='completed')item.completedOn=v.get('completedOn');closeDialog();refreshAfterChange();toast('Learning notes saved.');return;}
    if(action==='feedback'){feedbackDialog(id);return;}
    if(action==='feedback-save'||action==='feedback-send'){const f=saveFeedback(id);if(!f)return;if(action==='feedback-send'){openForms(f);render();}else{closeDialog();render();toast('Feedback saved on this browser.');}return;}
    if(action==='feedback-resend'){const f=learner.feedback.find(f=>f.id===id);if(f)openForms(f);return;}
    if(action==='feedback-confirm'){const f=learner.feedback.find(f=>f.id===id);if(f){f.delivery='reported-submitted';f.reportedSubmittedOn=new Date().toISOString();}closeDialog();refreshAfterChange();toast('Your submission confirmation is recorded.');return;}
    if(action==='compare-toggle'){if(ui.compared.includes(id))ui.compared=ui.compared.filter(x=>x!==id);else if(ui.compared.length<3)ui.compared.push(id);else{toast('Compare up to three offerings at a time.');return;}render();openCourse(id);return;}
    if(action==='compare-open'){compareDialog();return;}
    if(action==='compare-clear'){ui.compared=[];render();return;}
    if(action==='need'){needDialog(el.dataset.track,el.dataset.need);return;}
    if(action==='need-search'){ui.filters={sort:'relevant',need:el.dataset.need};ui.query='';ui.page=0;navigate('explore');return;}
    if(action==='onboarding'){showQuickSetup();return;}
    if(action==='retake'){showStartingChecks();return;}
    if(action==='backup'){download('my-ai-learning-backup.json',JSON.stringify(learner,null,2));return;}
    if(action==='corrupt-backup'){download('original-learning-data.txt',corruptBackup,'text/plain');return;}
    if(action==='restore'){pickFile('backup');return;}
    if(action==='restore-confirm'){learner=migrateLearner(B,ui.pendingBackup);ui.pendingBackup=null;corruptBackup='';closeDialog();refreshAfterChange();toast('Backup restored. Review your four learning layers and any catalog changes.');return;}
    if(action==='plan-csv'){download('my-ai-learning-plan.csv',exportPlan(B,learner),'text/csv');return;}
    if(action==='print'){ui.view='plan';ui.planTab='all';render();window.print();return;}
    if(action==='export-feedback'){download('my-course-feedback.json',JSON.stringify({schema:'ai-learning-feedback/1',feedback:learner.feedback},null,2));return;}
    if(action==='review-update'){reviewUpdate();return;}
    if(action==='acknowledge-update'){learner.history.push({date:new Date().toISOString(),event:'Reviewed central update',previous:learner.acknowledged,current:signature(B)});learner.acknowledged=signature(B);closeDialog();refreshAfterChange();return;}
    if(action==='import-central'){pickFile('central');return;}
    if(action==='export-central'){download('central-learning-pathway.json',JSON.stringify(B.scenario,null,2));return;}
    if(action==='central-confirm'){B.scenario=ui.pendingCentral;B.scenarioVersion=fingerprint(B.scenario);centralOverride=true;try{localStorage.setItem(STORAGE_KEY+'-central',JSON.stringify({scenario:B.scenario,version:B.scenarioVersion}));}catch{toast('Plan loaded for this session; browser storage is unavailable.');}ui.pendingCentral=null;closeDialog();render();toast('Central pathway loaded locally. Your personal plan is preserved.');return;}
    if(action==='reset-central'){B.scenario=structuredClone(embeddedScenario);B.scenarioVersion=embeddedVersion;centralOverride=false;try{localStorage.removeItem(STORAGE_KEY+'-central');}catch{}render();return;}
    if(action==='forms-save'){const value=$('#forms-template').value.trim();validateFormsTemplate(value);learner.formsTemplate=value;learner.formsDisabled=false;refreshAfterChange();toast('Forms connection saved on this browser.');return;}
    if(action==='forms-clear'){learner.formsTemplate='';learner.formsDisabled=true;refreshAfterChange();toast('Forms disconnected on this browser.');return;}
    if(action==='forms-test'){const value=$('#forms-template').value.trim();validateFormsTemplate(value);const c=B.catalogue.courses[0],g=groupFor(B,learner),sample={id:'TEST-DO-NOT-SUBMIT',courseId:c.id,courseTitle:c.title,groupId:g.id,groupName:g.name,catalogueVersion:B.catalogue.version,completedOn:B.config.releaseDate,usefulness:4,difficulty:'About right',actualHours:1.5,comment:'Test only: check spaces, &, apostrophes, and accented text café.'};const url=feedbackUrl(value,sample);showDialog('Test the prefilled form',`<p>Open this link and check that every field is populated correctly. This is test data; do not submit it as real learner feedback.</p><p>${external(url,'Open test form')}</p><p class="tiny-note">Verify sign-in, all eleven fields, special characters, and that someone can submit feedback for multiple courses.</p>`,button('Close','close'));return;}
    if(action==='export-config'){const value=$('#forms-template').value.trim();if(value)validateFormsTemplate(value);download('learning-path-config.json',JSON.stringify({...B.config,formsTemplate:value},null,2));return;}
    if(action==='import-feedback'){pickFile('feedback');return;}
    if(action==='load-local-feedback'){adminFeedback=summariseFeedback([...adminFeedback,...learner.feedback],B).responses;render();return;}
    if(action==='clear-admin-feedback'){adminFeedback=[];render();return;}
    if(action==='feedback-comments'){const g=summariseFeedback(adminFeedback,B).groups[Number(el.dataset.index)];showDialog('Feedback to review',`<h3>${esc(g.courseTitle)}</h3><p class="muted">${esc(g.groupName)} · ${g.count} responses</p>${g.responses.map(f=>`<div class="evidence-row"><strong>${f.usefulness}/5 · ${esc(f.difficulty)}</strong><p>${esc(f.comment||'No comment provided.')}</p><small>${formatHours(f.actualHours)} · Completed ${esc(f.completedOn)}</small></div>`).join('')}`,button('Close','close'));return;}
    if(action==='export-reviewed-feedback'){if(!$('#feedback-reviewed').checked)throw Error('Review the responses and check the confirmation before exporting a published aggregate.');const current=adminFeedback.filter(f=>f.catalogueVersion===B.catalogue.version);if(!current.length)throw Error('No responses match the current catalog version.');download('reviewed-learning-feedback.json',JSON.stringify(reviewedSummary(current,B),null,2));return;}
  }catch(e){error(e.message);}
});
document.addEventListener('change',event=>{const el=event.target;try{
  if(el.name==='learning-route'){if(!['standard','coached'].includes(el.value))throw Error('Choose a learning route.');learner.profile.learningRoute=el.value;refreshAfterChange();return;}
  if(el.closest('#quick-setup-form')){const message=$('#dialog-error');message.textContent='';message.className='';return;}
  if(el.name==='tools'){el.closest('.tool-choice').querySelector('.tool-purpose').hidden=!el.checked;}
  if(el.name==='central-profile'){const scope=applyScopeChoice(B,learner.profile,el.value).centralScope;el.closest('.central-scope-editor').querySelector('.scope-preview').innerHTML=scopeSummary(scope);const form=el.closest('form'),draft=readRoleChoices(new FormData(form),learner.profile);draft.level=Number(new FormData(form).get('level'));draft.centralScope=scope;form.querySelector('.activity-questions').innerHTML=activityQuestions(draft);}
  if(el.name==='roles'||el.name.startsWith('responsibility-')||el.name==='level'){
    const form=el.closest('form'),base=learner.profile;
    const values=new FormData(form),draft=readRoleChoices(values,base);draft.level=Number(values.get('level'));if(form.id==='profile-form')draft.centralScope=applyScopeChoice(B,base,values.get('central-profile')).centralScope;
    if(el.name==='roles'){const body=form.querySelector('[data-role-choices="'+el.value+'"]');body.hidden=!el.checked;el.setAttribute('aria-expanded',String(el.checked));}
    const guidance=form.querySelector('.starting-guidance');if(guidance)guidance.outerHTML=startingGuidance(draft);
    const questions=form.querySelector('.activity-questions');if(questions)questions.innerHTML=activityQuestions(draft);
  }
  if(el.id==='coverage-mode'){ui.coverageMode=el.value;ui.coverageOpen=true;render();}
  if(el.id.startsWith('filter-')){const key=el.id.slice(7);ui.filters[key]=el.type==='checkbox'?el.checked:el.value;ui.page=0;render();}
  if(el.id==='search-sort'){ui.filters.sort=el.value;$('#explore-results').innerHTML=exploreResults();}
  if(el.dataset.itemStatus){const id=el.dataset.itemStatus;if(!courseMap(B).has(id)){learner.items[id].status=el.value;if(el.value==='completed')learner.items[id].completedOn=localDate();else delete learner.items[id].completedOn;refreshAfterChange();return;}setStatus(B,learner,id,el.value);refreshAfterChange();if(el.value==='completed')feedbackDialog(id);}
  if(el.dataset.itemDate){learner.items[el.dataset.itemDate].dueDate=el.value;save();}
}catch(e){error(e.message);if(el.dataset.itemStatus)render();}});
let searchTimer;
document.addEventListener('input',event=>{if(event.target.id==='course-search'){ui.query=event.target.value;ui.page=0;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(ui.view==='explore'&&$('#explore-results'))$('#explore-results').innerHTML=exploreResults();},160);}});
document.addEventListener('toggle',event=>{if(event.target.id==='coverage-details')ui.coverageOpen=event.target.open;},true);
document.addEventListener('submit',event=>{event.preventDefault();try{
  if(event.target.id==='quick-setup-form'){saveQuickSetup(event.target);return;}
  if(event.target.id==='starting-checks-form'){
    if(!event.target.reportValidity())return;
    const values=new FormData(event.target);learner.profile.answers=Object.fromEntries(CHECKS.map(q=>[q.id,Number(values.get(q.id))]));save();closeDialog();
    const draft={...learner.profile,level:Number($('#profile-form [name="level"]:checked')?.value||learner.profile.level)};
    const guidance=$('#profile-form .starting-guidance');if(guidance)guidance.outerHTML=startingGuidance(draft);
    toast(`Starting point saved: L${startingPoint(draft).level} practice. Your target level is unchanged.`);return;
  }
  if(event.target.id==='profile-form'){const form=event.target;if(!form.reportValidity())return;const values=new FormData(form),previous=groupFor(B,learner).id,previousScope=structuredClone(learner.profile.centralScope);const profile=validatePathChoices({...readRoleChoices(values,learner.profile),name:values.get('name').trim(),level:Number(values.get('level')),experience:values.get('experience'),codingReady:values.has('codingReady'),...readToolChoices(values),centralScope:applyScopeChoice(B,learner.profile,values.get('central-profile')).centralScope,targetReview:null,levelGoal:Number(values.get('level')),priorLearning:values.get('priorLearning').trim()});learner.profile=profile;if(JSON.stringify(previousScope)!==JSON.stringify(profile.centralScope))learner.history.push({date:new Date().toISOString(),event:'Changed central outcome scope',previous:previousScope,current:structuredClone(profile.centralScope)});if(previous!==groupFor(B,learner).id)learner.history.push({date:new Date().toISOString(),event:'Changed learning layers',previous,current:groupFor(B,learner).id});learner.onboarding=true;refreshAfterChange();toast('Your four-layer path is saved. Your personal plan is preserved.');}}catch(e){error(e.message);}});
$('#file-input').addEventListener('change',async event=>{try{await importFile(event.target.files[0]);}catch(e){toast(e.message);}});
$('#dialog').addEventListener('cancel',()=>{ui.dialog=null;});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['for-you','explore','plan','profile','admin'].includes(view)&&view!==ui.view){ui.view=view;closeDialog();render();}});
try{render();if(!learner.onboarding&&ui.view==='for-you')setTimeout(()=>showQuickSetup(),150);}catch(e){$('#app').innerHTML=`<div class="loading"><h1>This learning space could not start.</h1><p>${esc(e.message)}</p><p>Your saved browser data has not been deleted.</p></div>`;console.error(e);}
